// SPDX-License-Identifier: AGPL-3.0-only
//! `kshana tlog`: the offline transparency-log verifier (`src/tlog.rs`, docs/TLOG.md).
//!
//! * RFC 6962 reference data: the Merkle tree hashes of the eight test leaves of the reference
//!   implementations, an inclusion proof and a consistency proof, as published numbers, and every
//!   inclusion and consistency proof up to eight leaves generated by an independent Python
//!   implementation (`tests/fixtures/tlog/gen_vectors.py`).
//! * The five-entry vector log: its leaf hashes, roots, chain head and proofs as given in the
//!   brief, rebuilt from entries served with sorted keys.
//! * Signed statements, a key history and a daily root with an RFC 3161 token, written by the
//!   Python generator with test keys from published seeds and a throwaway OpenSSL authority;
//!   each is verified, then tampered and refused.
//!
//! PIN-SCOPE: the published RFC 6962 vectors, the brief's vector-log hashes and the committed
//!   fixtures under tests/fixtures/tlog/.
//! PIN-EXCLUDES: any real log, service, key or timestamp authority; non-ASCII text in canonical
//!   JSON (the fixtures are ASCII).

use kshana::tlog::*;
use serde_json::Value;
use std::process::Command;

const KEY0: &str = "23c073fa9725b2bae0e5e6d95cf89a86c582de9061b9d8beccac09aeacde61d8";
const KEY1: &str = "986c89ffac474571e735964003e19120a98cbf7421a709825a4e802345c5864f";

fn fx(name: &str) -> String {
    format!("{}/tests/fixtures/tlog/{name}", env!("CARGO_MANIFEST_DIR"))
}

fn text(name: &str) -> String {
    std::fs::read_to_string(fx(name)).unwrap()
}

fn json(name: &str) -> Value {
    serde_json::from_str(&text(name)).unwrap()
}

fn h(s: &str) -> Hash {
    let mut o = [0u8; 32];
    hex::decode_to_slice(s, &mut o).unwrap();
    o
}

fn hs(v: &[&str]) -> Vec<Hash> {
    v.iter().map(|s| h(s)).collect()
}

fn key1() -> Opts<'static> {
    Opts {
        keys: Some(KeySource::Key(key_of_hex(KEY1).unwrap())),
        format: None,
    }
}

fn failed(r: &Report) -> Vec<String> {
    r.checks
        .iter()
        .filter(|c| !c.pass)
        .map(|c| c.id.clone())
        .collect()
}

#[test]
fn the_test_keys_come_from_their_published_seeds() {
    assert_eq!(test_key_hex("tlog test vector key 0"), KEY0);
    assert_eq!(test_key_hex("tlog test vector key 1"), KEY1);
}

#[test]
fn rfc6962_published_vectors() {
    let leaves: Vec<Hash> = [
        "",
        "00",
        "10",
        "2021",
        "3031",
        "40414243",
        "5051525354555657",
        "606162636465666768696a6b6c6d6e6f",
    ]
    .iter()
    .map(|x| leaf_hash(&hex::decode(x).unwrap()))
    .collect();
    let roots = [
        "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
        "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
        "fac54203e7cc696cf0dfcb42c92a1d9dbaf70ad9e621f4bd8d98662f00e3c125",
        "aeb6bcfe274b70a14fb067a5e5578264db0fa9b51af5e0ba159158f329e06e77",
        "d37ee418976dd95753c1c73862b9398fa2a2cf9b4ff0fdfe8b30cd95209614b7",
        "4e3bbb1f7b478dcfe71fb631631519a3bca12c9aefca1612bfce4c13a86264d4",
        "76e67dadbcdf1e10e1b74ddc608abd2f98dfb16fbce75277b5232a127f2087ef",
        "ddb89be403809e325750d3d263cd78929c2942b7942a34b77e122c9594a74c8c",
        "5dc9da79a70659a9ad559cb701ded9a2ab9d823aad2f4960cfe370eff4604328",
    ];
    for (n, r) in roots.iter().enumerate() {
        assert_eq!(hex::encode(mth(&leaves[..n])), *r, "MTH of {n} leaves");
    }
    let inc = hs(&[
        "96a296d224f285c67bee93c30f8a309157f0daa35dc5b87e410b78630a09cfc7",
        "5f083f0a1a33ca076a95279832580db3e0ef4584bdff1f54c8a360f50de3031e",
        "6b47aaf29ee3c2af9af889bc1fb9254dabd31177f16232dd6aab035ca39bf6e4",
    ]);
    assert_eq!(
        root_from_inclusion(0, 8, &leaves[0], &inc).unwrap(),
        h(roots[8])
    );
    let cons = hs(&[
        "0ebc5d3437fbe2db158b9f126a1d118e308181031d0a949f8dededebc558ef6a",
        "ca854ea128ed050b41b35ffc1b87b8eb2bde461e9e3b5596ece6b9d5975a0ae0",
        "d37ee418976dd95753c1c73862b9398fa2a2cf9b4ff0fdfe8b30cd95209614b7",
    ]);
    verify_consistency(6, 8, &h(roots[6]), &h(roots[8]), &cons).unwrap();
    // Wrong roots, sizes or paths are refused.
    assert!(verify_consistency(6, 8, &h(roots[5]), &h(roots[8]), &cons).is_err());
    assert!(verify_consistency(6, 8, &h(roots[6]), &h(roots[7]), &cons).is_err());
    assert!(verify_consistency(5, 8, &h(roots[5]), &h(roots[8]), &cons).is_err());
    assert!(verify_consistency(6, 8, &h(roots[6]), &h(roots[8]), &cons[..2]).is_err());
    assert!(verify_consistency(8, 6, &h(roots[8]), &h(roots[6]), &cons).is_err());
    // m == n: an empty path and equal roots.
    verify_consistency(8, 8, &h(roots[8]), &h(roots[8]), &[]).unwrap();
    assert!(verify_consistency(8, 8, &h(roots[8]), &h(roots[7]), &[]).is_err());
    assert!(verify_consistency(8, 8, &h(roots[8]), &h(roots[8]), &cons[..1]).is_err());
}

#[test]
fn every_proof_up_to_eight_leaves_from_the_independent_generator() {
    let d = json("rfc6962.json");
    let leaves: Vec<Hash> = d["leaves_hex"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| leaf_hash(&hex::decode(x.as_str().unwrap()).unwrap()))
        .collect();
    let roots: Vec<Hash> = d["roots"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| h(x.as_str().unwrap()))
        .collect();
    let path = |v: &Value| -> Vec<Hash> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|x| h(x.as_str().unwrap()))
            .collect()
    };
    let mut n_inc = 0;
    for p in d["inclusion"].as_array().unwrap() {
        let (m, n) = (p["index"].as_u64().unwrap(), p["size"].as_u64().unwrap());
        let pp = path(&p["path"]);
        assert_eq!(
            root_from_inclusion(m, n, &leaves[m as usize], &pp).unwrap(),
            roots[n as usize],
            "inclusion {m} in {n}"
        );
        // Another leaf at the same index does not prove.
        let other = leaves[(m as usize + 1) % 8];
        if other != leaves[m as usize] {
            assert_ne!(
                root_from_inclusion(m, n, &other, &pp).ok(),
                Some(roots[n as usize])
            );
        }
        n_inc += 1;
    }
    let mut n_cons = 0;
    for p in d["consistency"].as_array().unwrap() {
        let (m, n) = (p["from"].as_u64().unwrap(), p["to"].as_u64().unwrap());
        let pp = path(&p["path"]);
        verify_consistency(m, n, &roots[m as usize], &roots[n as usize], &pp)
            .unwrap_or_else(|e| panic!("consistency {m} -> {n}: {e}"));
        if m > 1 {
            assert!(
                verify_consistency(m, n, &roots[m as usize - 1], &roots[n as usize], &pp).is_err()
            );
        }
        n_cons += 1;
    }
    assert_eq!((n_inc, n_cons), (36, 36));
}

const VECTOR_LEAVES: [&str; 5] = [
    "daa5dec9e6bf803f06455afa747f80fae39ca14922ae8e91cbcad4263ef36898",
    "bc82554f325d9a2cdf63a9722a4e5e139c525cd698a2092b2c551778c65c0bfc",
    "865fb9be022be18d8d87b3805694c2f0417db3c11c48b84ab1b751f423f3a125",
    "806a222db27599cea68daa8a8694740d7a8b0c399d2d91dcee4421b0900ae95e",
    "268fa69821fd7b65522f9bbb5c346568c085d8d4e95300f0ca1ab8b1c6a5682f",
];

#[test]
fn the_vector_log_from_entries_served_with_sorted_keys() {
    let entries = parse_entries(&text("entries.jsonl")).unwrap();
    assert_eq!(entries.len(), 5);
    // Served sorted: "class" (when present) comes first in the file.
    assert!(text("entries.jsonl")
        .lines()
        .nth(1)
        .unwrap()
        .starts_with("{\"class\""));
    let mut leaves = Vec::new();
    let mut classes = Vec::new();
    for (i, e) in entries.iter().enumerate() {
        let (b, c) = leaf_bytes(e).unwrap();
        let lh = leaf_hash(&b);
        assert_eq!(hex::encode(lh), VECTOR_LEAVES[i], "leaf {i}");
        leaves.push(lh);
        classes.push(c);
    }
    assert_eq!(
        classes,
        [
            EntryClass::EvidencePack,
            EntryClass::EvidencePack,
            EntryClass::CalibrationRecord,
            EntryClass::EvidencePack,
            EntryClass::CalibrationRecord
        ]
    );
    assert_eq!(
        hex::encode(mth(&leaves[..3])),
        "6ecd73fa5a59588f78cc9cccd5f9b3b6e7f595d7d4c838117c57ad4dd8a58276"
    );
    assert_eq!(
        hex::encode(mth(&leaves)),
        "cb451fcf8acd96d640384218c8ab28380398dcf5850465fd72448e5bff545e94"
    );
    assert_eq!(
        hex::encode(chain_head(&leaves)),
        "553a5cb27cb83d5ff7d7d5ab577ef7b00710a4fea6b188660cb4d7a93d940b2d"
    );
    let inc = hs(&[
        "806a222db27599cea68daa8a8694740d7a8b0c399d2d91dcee4421b0900ae95e",
        "c42db437f39134febba44baf0db0841e4e7019874c648833495f417afa2f0594",
        "268fa69821fd7b65522f9bbb5c346568c085d8d4e95300f0ca1ab8b1c6a5682f",
    ]);
    assert_eq!(
        root_from_inclusion(2, 5, &leaves[2], &inc).unwrap(),
        mth(&leaves)
    );
    let cons = hs(&[
        "865fb9be022be18d8d87b3805694c2f0417db3c11c48b84ab1b751f423f3a125",
        "806a222db27599cea68daa8a8694740d7a8b0c399d2d91dcee4421b0900ae95e",
        "c42db437f39134febba44baf0db0841e4e7019874c648833495f417afa2f0594",
        "268fa69821fd7b65522f9bbb5c346568c085d8d4e95300f0ca1ab8b1c6a5682f",
    ]);
    verify_consistency(3, 5, &mth(&leaves[..3]), &mth(&leaves), &cons).unwrap();
}

#[test]
fn signed_tree_heads_and_proofs_verify_and_tampering_is_refused() {
    let entries = parse_entries(&text("entries.jsonl")).unwrap();
    let r = verify_sth(&json("sth-5.json"), Some(&entries), &key1()).unwrap();
    assert!(r.pass, "{}", r.to_text());
    assert_eq!(r.facts["entries.calibration_record"], 2);
    // The statement's format can be required.
    let mut o = key1();
    o.format = Some("example-sth/1".into());
    assert!(verify_sth(&json("sth-5.json"), None, &o).unwrap().pass);
    o.format = Some("other/1".into());
    assert_eq!(
        failed(&verify_sth(&json("sth-5.json"), None, &o).unwrap()),
        ["sth.format"]
    );
    // Another key, a changed payload, a changed entry.
    let k0 = Opts {
        keys: Some(KeySource::Key(key_of_hex(KEY0).unwrap())),
        format: None,
    };
    assert_eq!(
        failed(&verify_sth(&json("sth-5.json"), None, &k0).unwrap()),
        ["sth.signature"]
    );
    let mut t = json("sth-5.json");
    t["verdict"]["size"] = 4.into();
    assert_eq!(
        failed(&verify_sth(&t, None, &key1()).unwrap()),
        ["sth.verdict-sha256", "sth.signature"]
    );
    let mut e2 = entries.clone();
    e2[1]["kind"] = "kshana-dossier/2".into();
    assert_eq!(
        failed(&verify_sth(&json("sth-5.json"), Some(&e2), &key1()).unwrap()),
        ["sth.root-from-entries", "sth.chain-head-from-entries"]
    );
    // Inclusion, with the entry and the tree head of its size.
    let r = verify_inclusion(
        &json("inclusion-2-of-5.json"),
        Some(&entries[2]),
        Some(&json("sth-5.json")),
        &key1(),
    )
    .unwrap();
    assert!(r.pass, "{}", r.to_text());
    let r = verify_inclusion(
        &json("inclusion-2-of-5.json"),
        Some(&entries[3]),
        Some(&json("sth-3.json")),
        &key1(),
    )
    .unwrap();
    assert_eq!(
        failed(&r),
        [
            "inclusion.leaf-hash",
            "inclusion.sth-size",
            "inclusion.sth-root"
        ]
    );
    // An unsigned proof is checked on its own and says so.
    let bare = json("inclusion-2-of-5.json")["verdict"].clone();
    let r = verify_inclusion(&bare, None, None, &Opts::default()).unwrap();
    assert!(r.pass);
    assert_eq!(r.facts["proof.signed"], false);
    // A signed proof without a key is an error, not a pass.
    assert!(
        verify_inclusion(&json("inclusion-2-of-5.json"), None, None, &Opts::default()).is_err()
    );
    // Consistency, against both tree heads.
    let r = verify_consistency_doc(
        &json("consistency-3-to-5.json"),
        Some(&json("sth-3.json")),
        Some(&json("sth-5.json")),
        &key1(),
    )
    .unwrap();
    assert!(r.pass, "{}", r.to_text());
    let r = verify_consistency_doc(
        &json("consistency-3-to-5.json"),
        Some(&json("sth-5.json")),
        None,
        &key1(),
    )
    .unwrap();
    assert_eq!(
        failed(&r),
        ["consistency.sth-from-size", "consistency.sth-from-root"]
    );
}

#[test]
fn the_key_history_verifies_and_supplies_keys_by_period() {
    let (r, hist) = verify_key_history(
        &text("key-history.jsonl"),
        Some(&key_of_hex(KEY0).unwrap()),
        None,
    )
    .unwrap();
    assert!(r.pass, "{}", r.to_text());
    let hist = hist.unwrap();
    assert_eq!(hist.periods.len(), 2);
    assert_eq!(
        hist.periods[0].not_after.as_deref(),
        Some("2026-11-01T00:00:00Z")
    );
    assert!(hist.periods[1].endorsed_by_previous);
    assert_eq!(
        hist.key_at("kid-log-1", "2026-11-20T00:00:00Z"),
        Some(key_of_hex(KEY1).unwrap())
    );
    assert_eq!(hist.key_at("kid-log-1", "2026-10-31T23:59:59Z"), None);
    assert_eq!(hist.key_at("kid-log-0", "2026-11-01T00:00:00Z"), None);
    assert_eq!(
        hist.key_at("kid-log-0", "2026-10-31T23:59:59Z"),
        Some(key_of_hex(KEY0).unwrap())
    );
    // Statements verified through the history.
    let o = Opts {
        keys: Some(KeySource::History(&hist)),
        format: None,
    };
    let r = verify_sth(&json("sth-5.json"), None, &o).unwrap();
    assert!(r.pass, "{}", r.to_text());
    // A wrong first key; a broken chain; a changed key; a missing middle record.
    let (r, h2) = verify_key_history(
        &text("key-history.jsonl"),
        Some(&key_of_hex(KEY1).unwrap()),
        None,
    )
    .unwrap();
    assert_eq!(failed(&r), ["record[0].first-key"]);
    assert!(h2.is_none());
    let lines: Vec<Value> = parse_entries(&text("key-history.jsonl")).unwrap();
    let mut l = lines.clone();
    l[1]["record"]["previous_record_sha256"] = "11".repeat(32).into();
    let joined: String = l.iter().map(|v| v.to_string() + "\n").collect();
    let (r, _) = verify_key_history(&joined, None, None).unwrap();
    assert!(failed(&r).contains(&"record[1].previous-record-sha256".to_string()));
    assert!(failed(&r).contains(&"record[1].self-signature".to_string()));
    let only_second: String = lines[1].to_string();
    let (r, _) = verify_key_history(&only_second, None, None).unwrap();
    assert!(failed(&r).contains(&"record[0].seq".to_string()));
    // The fixtures write the algorithm "Ed25519", as the producer does; any case is accepted,
    // and a record whose algorithm is not Ed25519 fails (and so does its self-signature,
    // which covers the field).
    assert_eq!(lines[0]["record"]["algorithm"], "Ed25519");
    let mut l = lines.clone();
    l[0]["record"]["algorithm"] = "ECDSA-P256".into();
    let joined: String = l.iter().map(|v| v.to_string() + "\n").collect();
    let (r, _) = verify_key_history(&joined, None, None).unwrap();
    assert!(failed(&r).contains(&"record[0].algorithm".to_string()));
    let mut l = lines.clone();
    l[1]["previous_key_endorsement"] = "00".repeat(64).into();
    let joined: String = l.iter().map(|v| v.to_string() + "\n").collect();
    let (r, _) = verify_key_history(&joined, None, None).unwrap();
    assert_eq!(failed(&r), ["record[1].endorsement"]);
}

#[test]
fn the_daily_root_and_its_rfc3161_timestamp() {
    let roots = kshana::evidence::tsa::pem_certificates(&text("tsa-root.pem")).unwrap();
    let tsa = TsaInputs {
        anchors: roots,
        untrusted: Vec::new(),
    };
    let r = verify_daily_root(&json("daily-root.json"), Some(&tsa), &key1()).unwrap();
    assert!(r.pass, "{}", r.to_text());
    // The stamped bytes are the canonical daily root, as committed.
    let doc = json("daily-root.json");
    assert_eq!(
        canonical_json(&doc["verdict"]["daily_root"]).as_bytes(),
        std::fs::read(fx("daily-root-stamped.bin"))
            .unwrap()
            .as_slice()
    );
    // Another authority root: the chain fails.
    let other = TsaInputs {
        anchors: kshana::evidence::tsa::pem_certificates(&text("tsa-other-root.pem")).unwrap(),
        untrusted: Vec::new(),
    };
    let r = verify_daily_root(&json("daily-root.json"), Some(&other), &key1()).unwrap();
    assert_eq!(failed(&r), ["timestamp[0].rfc3161"]);
    // No roots given: the token's signature is not checked, which is a failure, not a pass.
    let r = verify_daily_root(&json("daily-root.json"), None, &key1()).unwrap();
    assert_eq!(failed(&r), ["timestamp[0].rfc3161"]);
    // A token whose stated digest does not match its bytes.
    let mut t = doc.clone();
    t["verdict"]["timestamps"][0]["token_sha256"] = "00".repeat(32).into();
    let r = verify_daily_root(&t, Some(&tsa), &key1()).unwrap();
    assert!(failed(&r).contains(&"timestamp[0].token-sha256".to_string()));
    // Unanchored: verifies, and says it is not anchored.
    let r = verify_daily_root(&json("daily-root-unanchored.json"), Some(&tsa), &key1()).unwrap();
    assert!(r.pass);
    assert!(r.facts.contains_key("anchored"));
}

#[test]
fn the_command_line() {
    let run = |args: &[&str]| {
        Command::new(env!("CARGO_BIN_EXE_kshana"))
            .arg("tlog")
            .args(args)
            .output()
            .unwrap()
    };
    let o = run(&[
        "verify-sth",
        &fx("sth-5.json"),
        "--key",
        KEY1,
        "--entries",
        &fx("entries.jsonl"),
        "--json",
    ]);
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let doc: Value = serde_json::from_slice(&o.stdout).unwrap();
    assert_eq!(doc["schema"], SCHEMA);
    assert_eq!(doc["pass"], true);
    let o = run(&[
        "verify-inclusion",
        &fx("inclusion-2-of-5.json"),
        "--key-history",
        &fx("key-history.jsonl"),
        "--sth",
        &fx("sth-5.json"),
    ]);
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let o = run(&[
        "verify-consistency",
        &fx("consistency-3-to-5.json"),
        "--key",
        KEY0,
    ]);
    assert!(!o.status.success());
    assert!(String::from_utf8_lossy(&o.stdout).contains("proof.signature"));
    let o = run(&[
        "verify-daily-root",
        &fx("daily-root.json"),
        "--key",
        KEY1,
        "--tsa-ca",
        &fx("tsa-root.pem"),
    ]);
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stdout));
    let o = run(&[
        "verify-key-history",
        &fx("key-history.jsonl"),
        "--first-key",
        KEY0,
    ]);
    assert!(o.status.success());
    // Usage errors.
    assert!(!run(&[]).status.success());
    assert!(!run(&["verify-sth", &fx("sth-5.json")]).status.success());
    assert!(!run(&["verify-sth", &fx("sth-5.json"), "--key", "zz"])
        .status
        .success());
    assert!(
        !run(&["verify-sth", &fx("sth-5.json"), "--key", KEY1, "--bogus"])
            .status
            .success()
    );
    assert!(!run(&[
        "verify-sth",
        &fx("sth-5.json"),
        "--key",
        KEY1,
        "--key-history",
        &fx("key-history.jsonl")
    ])
    .status
    .success());
}
